use super::*;
use std::{
    alloc::{GlobalAlloc, Layout, System},
    cell::Cell,
};
struct Alloc;
thread_local! {static COUNT:Cell<Option<usize>>=const{Cell::new(None)};}
#[global_allocator]
static ALLOC: Alloc = Alloc;
unsafe impl GlobalAlloc for Alloc {
    unsafe fn alloc(&self, l: Layout) -> *mut u8 {
        COUNT.with(|c| {
            if let Some(n) = c.get() {
                c.set(Some(n + 1))
            }
        });
        unsafe { System.alloc(l) }
    }
    unsafe fn dealloc(&self, p: *mut u8, l: Layout) {
        COUNT.with(|c| {
            if let Some(n) = c.get() {
                c.set(Some(n + 1))
            }
        });
        unsafe { System.dealloc(p, l) }
    }
    unsafe fn realloc(&self, p: *mut u8, l: Layout, n: usize) -> *mut u8 {
        COUNT.with(|c| {
            if let Some(n) = c.get() {
                c.set(Some(n + 1))
            }
        });
        unsafe { System.realloc(p, l, n) }
    }
}
fn no_alloc(f: impl FnOnce()) {
    COUNT.with(|c| c.set(Some(0)));
    f();
    let n = COUNT.with(|c| c.replace(None).unwrap());
    assert_eq!(n, 0, "audio callback allocation/free");
}

#[test]
fn riser_matches_pinned_upstream_cpp_reference() {
    // Generated by the unmodified upstream RiserDSP.hpp (see upstream/null-riser).
    let reference = include_str!("../upstream/null-riser/reference.csv");
    let mut lines = reference.lines();
    for rate in [8000., 48000., 192000.] {
        let p = FxParams::new(&specs::RISER);
        let mut dsp = riser::BuildUp::default();
        dsp.prepare(rate, &p);
        for block in 0..240 {
            let amount = match block { 0..8 => 0, 8..48 => 25, 48..96 => 100, 96..128 => 40, _ => 0 };
            set(&p, 0, amount);
            let mut l = std::array::from_fn::<_, 512, _>(|i| (((block * 512 + i) % 97) as i32 - 48) as f32 / 256.);
            let mut r = std::array::from_fn::<_, 512, _>(|i| (((block * 512 + i) % 73) as i32 - 36) as f32 / 384.);
            no_alloc(|| dsp.audio(&mut l, &mut r, &p));
            for i in [0, 71, 255, 511] {
                let line = lines.next().unwrap();
                let fields: Vec<f64> = line.split(',').map(|x| x.parse().unwrap()).collect();
                assert_eq!(&fields[..3], &[rate as f64, block as f64, i as f64]);
                for (actual, expected) in [(l[i], fields[3]), (r[i], fields[4])] {
                    assert!((actual as f64 - expected).abs() < 2e-6, "{line}: {actual}");
                }
            }
        }
    }
    assert!(lines.next().is_none());
}

#[test]
fn riser_dry_sweep_reset_and_nonfinite_input() {
    for rate in [8000., 44100., 48000., 96000., 192000.] {
        let p = FxParams::new(&specs::RISER);
        let mut dsp = riser::BuildUp::default();
        dsp.prepare(rate, &p);
        let original = tone(512, rate as f64, 440., 0.1);
        let mut l = original.clone();
        let mut r = l.clone();
        no_alloc(|| dsp.audio(&mut l, &mut r, &p));
        assert_eq!(l, original);
        assert_eq!(r, original);
        set(&p, 0, 100);
        for _ in 0..(rate as usize / 512 + 1) {
            l.copy_from_slice(&original);
            r.copy_from_slice(&original);
            no_alloc(|| dsp.audio(&mut l, &mut r, &p));
            assert!(l.iter().chain(&r).all(|x| x.is_finite() && x.abs() < 10.));
        }
        assert_ne!(l, original);
        assert_ne!(l, r, "independent noise and stereo wash");
        set(&p, 0, 0);
        for _ in 0..(rate as usize / 512 + 1) {
            l.copy_from_slice(&original);
            r.copy_from_slice(&original);
            dsp.audio(&mut l, &mut r, &p);
        }
        assert_eq!(l, original);
        assert_eq!(r, original);
        no_alloc(|| dsp.reset(&p));
        l.fill(f32::NAN);
        r.fill(f32::INFINITY);
        no_alloc(|| dsp.audio(&mut l, &mut r, &p));
        assert!(l.iter().chain(&r).all(|x| *x == 0.));
    }
}

#[test]
fn riser_editor_drag_typed_reset_and_render() {
    use ml_small_fx::editor::{Btn, Logic, Mods};
    let params = Arc::new(FxParams::new(&specs::RISER));
    let mut shared = Shared::default();
    shared.extension = Some(riser::BuildUp::default().panel(params.clone()));
    let mut logic = Logic::new(&specs::RISER, params.clone(), Arc::new(shared), None);
    let output = std::path::PathBuf::from(std::env::var("ML_TOOLS_RENDER_DIR").unwrap());
    for scale in [1., 1.5, 2.] {
        let mut canvas = Canvas::new((560. * scale) as u32, (270. * scale) as u32, scale).unwrap();
        logic.paint(&mut canvas, &os_theme::Palette::default());
        assert!(logic.hits.iter().any(|h| h.t.id() == "intensity"));
        canvas.pixmap.save_png(output.join(format!("ML Riser {scale}.png"))).unwrap();
    }
    logic.down(111., 106., Btn::Left, Mods::default(), false);
    logic.delta(0., -50., Mods::default());
    logic.up(Btn::Left);
    assert!(params.v(0) > 0);
    logic.typed("intensity", "75%");
    assert_eq!(params.v(0), 75);
    logic.typed("intensity", "NaN");
    assert_eq!(params.v(0), 75);
    logic.down(111., 106., Btn::Middle, Mods::default(), false);
    assert_eq!(params.v(0), 0);
}
fn set(p: &FxParams, i: usize, v: i32) {
    p.live.set(p.p[i].as_ptr(), p.p[i].preview_normalized(v));
}
fn tone(n: usize, rate: f64, f: f64, a: f32) -> Vec<f32> {
    (0..n)
        .map(|i| (std::f64::consts::TAU * f * i as f64 / rate).sin() as f32 * a)
        .collect()
}
fn rms(x: &[f32]) -> f64 {
    (x.iter().map(|x| (*x as f64).powi(2)).sum::<f64>() / x.len() as f64).sqrt()
}
#[test]
fn frequency_translation_sidebands_stereo_and_dry() {
    for rate in [8000., 44100., 48000., 96000., 192000.] {
        let p = FxParams::new(&specs::FREQUENCY);
        set(&p, 0, 2500);
        set(&p, 1, 1);
        let mut s = frequency::Shifter::default();
        s.prepare(rate as f32, &p);
        let input = tone(rate as usize, rate, 1000., 0.2);
        let mut l = input.clone();
        let mut r = l.clone();
        no_alloc(|| s.audio(&mut l, &mut r, &p));
        let amplitude = |v: &[f32], hz: f64| {
            let mut re = 0.;
            let mut im = 0.;
            for (i, x) in v[v.len() / 2..].iter().enumerate() {
                let phase = std::f64::consts::TAU * hz * i as f64 / rate;
                re += *x as f64 * phase.cos();
                im += *x as f64 * phase.sin();
            }
            (re * re + im * im).sqrt() * 4. / v.len() as f64
        };
        for (out, want, unwanted) in [(&l, 1250., 750.), (&r, 750., 1250.)] {
            let a = amplitude(out, want);
            let b = amplitude(out, unwanted);
            assert!(a > 0.15 && a < 0.23, "gain {rate} {want}: {a}");
            assert!(b < a * 0.018, "image rejection {rate}: {a} {b}");
        }
        set(&p, 2, 0);
        s.reset(&p);
        l.copy_from_slice(&input);
        r.copy_from_slice(&input);
        no_alloc(|| s.audio(&mut l, &mut r, &p));
        assert_eq!(l, input);
        assert_eq!(r, input);
        s.reset(&p);
        l.fill(0.);
        r.fill(0.);
        s.audio(&mut l, &mut r, &p);
        assert_eq!(rms(&l), 0.);
    }
}
#[test]
fn tuner_accuracy_harmonics_silence_noise_and_calibration() {
    for rate in [8000., 22050., 24000.] {
        for hz in [27.6, 41.203, 82.4069, 220., 440., 659.255, 1318.51, 1975.53] {
            let frame = std::array::from_fn(|i| {
                let p = std::f64::consts::TAU * hz * i as f64 / rate;
                (0.2 * p.sin() + 0.3 * (p * 2.).sin() + 0.1 * (p * 3.).sin()) as f32
            });
            let (result, confidence) = tuner::estimate(&frame, 0, rate, 0.001);
            let cents = (1200. * (result as f64 / hz).log2()).abs();
            assert!(
                cents < 3.,
                "{rate} {hz}: {result} {cents} cents conf {confidence}"
            );
        }
    }
    let silence = [0.; 3072];
    assert!(!tuner::estimate(&silence, 0, 24000., 0.001).0.is_finite());
    let dc = [0.1; 3072];
    assert!(!tuner::estimate(&dc, 0, 24000., 0.001).0.is_finite());
    let mut seed = 17u32;
    let noise = std::array::from_fn(|_| {
        seed = seed.wrapping_mul(1664525).wrapping_add(1013904223);
        seed as i32 as f32 / i32::MAX as f32 * 0.1
    });
    assert!(!tuner::estimate(&noise, 0, 24000., 0.001).0.is_finite());
    let quiet = std::array::from_fn(|i| (i as f32 * 0.1).sin() * 0.0001);
    assert!(!tuner::estimate(&quiet, 0, 24000., 0.001).0.is_finite());
    assert_eq!(tuner::note(442., 442.).0, "A4");
    assert!(tuner::note(442., 442.).1.abs() < 0.001);
    assert!((tuner::note(440. * 2f32.powf(0.25 / 12.), 440.).1 - 25.).abs() < 0.001);
}
#[test]
fn tuner_worker_passthrough_mute_reset_and_stale_reading() {
    let p = FxParams::new(&specs::TUNER);
    let mut d = tuner::Detector::default();
    d.prepare(48000., &p);
    let mut at = 0;
    for _ in 0..75 {
        let mut l: Vec<f32> = (0..512)
            .map(|i| ((at + i) as f64 * std::f64::consts::TAU * 220. / 48000.).sin() as f32 * 0.2)
            .collect();
        let input = l.clone();
        let mut r = vec![0.; 512];
        no_alloc(|| d.audio(&mut l, &mut r, &p));
        assert_eq!(l, input);
        at += 512;
        std::thread::sleep(std::time::Duration::from_millis(5));
    }
    assert!((d.reading() - 220.).abs() < 0.3, "{}", d.reading());
    set(&p, 3, 1);
    let mut l = [0.2; 1024];
    let mut r = l;
    no_alloc(|| d.audio(&mut l, &mut r, &p));
    assert_eq!(l[1023], 0.);
    no_alloc(|| d.reset(&p));
    assert!(!d.reading().is_finite());
    std::thread::sleep(std::time::Duration::from_millis(550));
    assert!(!d.reading().is_finite());
}
#[test]
fn multiband_delay_echo_timing_crossover_sum_and_tempo() {
    for rate in [8000., 44100., 48000., 96000., 192000.] {
        let p = FxParams::new(&specs::MULTIDELAY);
        set(&p, 4, 0);
        set(&p, 2, 1000);
        for b in 0..3 {
            set(&p, 5 + b * 4, 50);
            set(&p, 7 + b * 4, 0);
        }
        let mut d = multidelay::Multidelay::default();
        d.prepare(rate as f32, &p);
        let n = (rate * 0.2) as usize;
        let mut l = vec![0.; n];
        l[0] = 0.2;
        let mut r = vec![0.; n];
        no_alloc(|| d.audio(&mut l, &mut r, &p));
        let mut split = ml_mix_core::split::Splitter::default();
        let g = [
            (std::f64::consts::PI * 250. / rate).tan(),
            (std::f64::consts::PI * 4000f64.min(rate * 0.45) / rate).tan(),
        ];
        let delay = rate * 0.05;
        let mut expected = vec![0f32; n];
        for i in 0..n {
            expected[i] = split
                .bands(0, if i == 0 { 0.2 } else { 0. }, g)
                .iter()
                .sum::<f64>() as f32;
        }
        let mut ring = os_engine::effects::delay::Ring::new((n * 2).next_power_of_two());
        for i in 0..n {
            let v = ring.read_clean(delay as f32);
            ring.write(expected[i]);
            assert!((l[i] - v).abs() < 2e-6, "{rate} {i}: {} {v}", l[i]);
        }
        assert_eq!(rms(&r), 0.);
        set(&p, 2, 0);
        d.reset(&p);
        let input = tone(n, rate, 440., 0.1);
        l.copy_from_slice(&input);
        r.copy_from_slice(&input);
        no_alloc(|| d.audio(&mut l, &mut r, &p));
        assert_eq!(l, input);
        assert_eq!(r, input);
    }
    let p = FxParams::new(&specs::MULTIDELAY);
    assert_eq!(multidelay::time_ms(&p, 0, 120.), 500.);
    assert_eq!(multidelay::time_ms(&p, 0, 60.), 1000.);
    assert_eq!(multidelay::time_ms(&p, 0, 10.), 4000.);
}
#[test]
fn effects_automation_and_feedback_remain_finite() {
    let p = FxParams::new(&specs::MULTIDELAY);
    let mut d = multidelay::Multidelay::default();
    d.prepare(48000., &p);
    let q = FxParams::new(&specs::FREQUENCY);
    let mut f = frequency::Shifter::default();
    f.prepare(48000., &q);
    for step in 0..80 {
        set(&p, 0, if step % 2 == 0 { 5000 } else { 20 });
        set(&p, 1, if step % 2 == 0 { 100 } else { 20000 });
        set(&p, 4, step % 2);
        for b in 0..3 {
            set(&p, 5 + 4 * b, 1 + step * 49);
            set(&p, 7 + 4 * b, 900);
        }
        d.tempo(Some(if step % 2 == 0 { 40. } else { 300. }));
        set(&q, 0, if step % 2 == 0 { 20000 } else { -20000 });
        set(&q, 1, step % 2);
        let mut l = [0.1; 1024];
        let mut r = [-0.1; 1024];
        no_alloc(|| d.audio(&mut l, &mut r, &p));
        assert!(l.iter().chain(&r).all(|v| v.is_finite() && v.abs() < 16.));
        no_alloc(|| f.audio(&mut l, &mut r, &q));
        assert!(l.iter().chain(&r).all(|v| v.is_finite() && v.abs() < 16.));
    }
    no_alloc(|| d.reset(&p));
    let mut l = [0.; 1024];
    let mut r = l;
    no_alloc(|| d.audio(&mut l, &mut r, &p));
    assert_eq!(rms(&l), 0.);
}
mod a {
    type Effect = super::frequency::FrequencyShift;
    os_plugkit::linked_clap_entry!(Effect);
}
mod b {
    type Effect = super::tuner::Tuner;
    os_plugkit::linked_clap_entry!(Effect);
}
mod c {
    type Effect = super::multidelay::MultibandDelay;
    os_plugkit::linked_clap_entry!(Effect);
}
#[test]
fn actual_host_state_latency_and_synced_echo() {
    use os_engine::HostedEffect as _;
    use os_host::Plugin as _;
    for (entry, name) in [
        (&a::LINKED_CLAP_ENTRY, "ML Frequency Shift"),
        (&b::LINKED_CLAP_ENTRY, "ML Tuner"),
        (&c::LINKED_CLAP_ENTRY, "ML Multiband Delay"),
    ] {
        let lib = unsafe {
            os_clap::Library::from_entry(
                entry as *const _ as *const std::ffi::c_void,
                std::path::Path::new("ML utility.clap"),
            )
        }
        .unwrap();
        assert_eq!(lib.plugins[0].name, name);
        let mut p = os_clap::Plugin::new(&lib, &lib.plugins[0].id).unwrap();
        assert!(p.activate(48000));
        assert_eq!(p.latency(), 0);
        if name == "ML Multiband Delay" {
            p.set_param(p.param_info(2).unwrap().id, 1.);
            for b in 0..3 {
                p.set_param(p.param_info(6 + b * 4).unwrap().id, 4. / 7.);
                p.set_param(p.param_info(7 + b * 4).unwrap().id, 0.);
            }
            p.transport_fx(&os_engine::TransportInfo {
                playing: true,
                tempo: 60.,
                frame: 0,
                beats: 0.,
                bar_start: 0.,
                bar: 0,
                numerator: 4,
                denominator: 4,
                looping: None,
            });
            let mut l = vec![0.; 60000];
            l[10000] = 0.2;
            let mut r = vec![0.; 60000];
            p.process_fx(48000, &mut l, &mut r);
            assert!(rms(&l[58000..59000]) > 0.001);
            assert!(
                rms(&l[34000..35000]) < 1e-6,
                "must follow 60 BPM rather than 120"
            );
        }
        for i in 0..p.param_count() {
            let id = p.param_info(i).unwrap().id;
            p.set_param(id, 0.37);
        }
        let mut l = [0.; 512];
        let mut r = l;
        p.process_fx(48000, &mut l, &mut r);
        p.idle();
        let saved = p.save_state().unwrap();
        let mut restored = os_clap::Plugin::new(&lib, &lib.plugins[0].id).unwrap();
        assert!(restored.load_state(&saved));
        assert!(restored.activate(48000));
        for i in 0..p.param_count() {
            let id = p.param_info(i).unwrap().id;
            assert_eq!(p.param_value(id), restored.param_value(id));
        }
    }
}
#[test]
fn parameter_text_and_stock_editor_renders() {
    struct Model(&'static Spec);
    impl ml_small_fx::view::Model for Model {
        fn norm(&self, id: &str) -> f32 {
            let p = &self.0.settings[self.0.index(id).unwrap()];
            (p.start - p.range.0) as f32 / (p.range.1 - p.range.0) as f32
        }
        fn plain(&self, id: &str) -> f32 {
            self.0.settings[self.0.index(id).unwrap()].start as f32
        }
        fn text(&self, id: &str) -> String {
            let i = self.0.index(id).unwrap();
            (self.0.text)(i, self.0.settings[i].start)
        }
    }
    for spec in [&specs::FREQUENCY, &specs::TUNER, &specs::MULTIDELAY] {
        for (i, p) in spec.settings.iter().enumerate() {
            for v in [p.range.0, p.start, p.range.1] {
                assert_eq!(
                    (spec.parse)(i, &(spec.text)(i, v)),
                    Some(v),
                    "{} {}",
                    spec.name,
                    p.id
                );
            }
        }
        let p = Arc::new(FxParams::new(spec));
        let mut f = frequency::Shifter::default();
        let t = tuner::Detector::default();
        let mut d = multidelay::Multidelay::default();
        let panel: Arc<dyn Extension> = match spec.name {
            "ML Frequency Shift" => {
                f.prepare(48000., &p);
                f.panel(p)
            }
            "ML Tuner" => {
                t.publish_test(440.2);
                t.panel(p)
            }
            _ => {
                d.prepare(48000., &p);
                let mut l = [0.; 1];
                let mut r = l;
                d.audio(&mut l, &mut r, &p);
                d.panel(p)
            }
        };
        for scale in [1., 1.5, 2.] {
            let mut canvas = Canvas::new(
                (spec.size.0 as f32 * scale) as u32,
                (spec.size.1 as f32 * scale) as u32,
                scale,
            )
            .unwrap();
            let model = Model(spec);
            ml_small_fx::view::paint(
                spec,
                &mut canvas,
                &os_theme::Palette::default(),
                &model,
                &Default::default(),
                "",
            );
            panel.paint(&mut canvas, &model);
            canvas
                .pixmap
                .save_png(
                    std::path::Path::new(&std::env::var("ML_TOOLS_RENDER_DIR").unwrap())
                        .join(format!("{} {scale}.png", spec.name)),
                )
                .unwrap();
        }
    }
}
